refentry.refsect1:
&reftitle.returnvalues;


 Restituisce il nome del limitatore di cache corrente.
 Se la modifica del valore fallisce, viene restituito &false;.

  &reftitle.examples;



    Esempio di session_cache_limiter


<?php

/* imposta il limitatore di cache a 'private' */

session_cache_limiter('private');
$cache_limiter = session_cache_limiter();

echo "Il limitatore di cache è ora impostato a $cache_limiter<br />";
?>
